{
  "title": "夜探秘境",
  "scene": "午夜，你站在一处古旧客栈的后院，四周静悄悄的，只有一盏摇曳的灯笼挂在院中。据传这里隐藏着一个神秘门派的入口，但寻常人无法找到。墙角有一堆看似无用的破布，旁边是一棵高大的古树。突然，一阵风吹过，墙上的一个木板似乎轻轻移动了一下。你回想起江湖中有传言，说真正的高手会利用自然之物，而轻功更是开门的钥匙。",
  "goal": "找到并进入神秘门派的入口",
  "clue": "墙上的木板是机关的入口，破布下可能有线索，古树可以用来施展轻功。",
  "choices": [
    {
      "id": "A",
      "text": "翻墙而入",
      "outcome": "你施展轻功跃上高墙，却发现墙上布满尖刺，轻功不够高超的你被划伤，只能退回原地。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "检查破布",
      "outcome": "你仔细检查破布，发现下面藏着一张旧地图，上面标注了进入神秘门派的方法。你按照地图上的指示，找到了墙上的机关，成功进入秘境。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "推动木板",
      "outcome": "你直接走向墙角，试图推动木板，却触发了机关，一阵机关声后，地面突然塌陷，你掉入了一个陷阱。虽然你最终挣扎着爬出来，但过程十分艰辛，体力消耗殆尽。",
      "result": "fail",
      "next": "next_level"
    }
  ]
}
